-- Synthetic enterprise database for Reports integration tests (no real company data).
-- Same physical model as Semantic's SyntheticCatalog, so plans generated by Semantic run unchanged.

CREATE SCHEMA plant;
CREATE SCHEMA finance;
CREATE SCHEMA docs;
CREATE SCHEMA "we""ird schema";

CREATE TABLE plant.equipment (
    id   int8 PRIMARY KEY,
    dbid int8 NOT NULL,
    name varchar(100)
);

CREATE TABLE plant.measurements (
    id             int8 PRIMARY KEY,
    equipment_dbid int8 NOT NULL,
    value          numeric(12, 3),
    measured_at    timestamptz NOT NULL,
    note           varchar(200),
    -- Wall-clock copies (UTC wall time) to test timestamp and date columns.
    measured_local timestamp,
    recorded_on    date
);

CREATE TABLE plant.sensors (
    id           int8 PRIMARY KEY,
    equipment_id int8 NOT NULL,
    vendor_code  varchar(10),
    label        varchar(50)
);

CREATE TABLE finance.transactions (
    id              int8 PRIMARY KEY,
    company_code    bpchar(4) NOT NULL,
    document_number varchar(20),
    amount          numeric(12, 2) NOT NULL
);

CREATE TABLE docs.documents (
    company_code bpchar(4) NOT NULL,
    number       varchar(20) NOT NULL,
    title        varchar(200),
    PRIMARY KEY (company_code, number)
);

CREATE TABLE "we""ird schema"."tab le" (
    id        int8 PRIMARY KEY,
    "va""lue" varchar(20)
);

