-- Read-only role used by Reports: CONNECT + USAGE + SELECT, nothing else.
CREATE ROLE nexora_reader LOGIN PASSWORD 'reader-test-password';
REVOKE ALL ON SCHEMA public FROM nexora_reader;
GRANT USAGE ON SCHEMA plant, finance, docs, "we""ird schema" TO nexora_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA plant, finance, docs, "we""ird schema" TO nexora_reader;

-- A misconfigured role with write privileges: Reports must refuse it.
CREATE ROLE nexora_writer LOGIN PASSWORD 'writer-test-password';
GRANT USAGE ON SCHEMA plant TO nexora_writer;
GRANT SELECT, INSERT ON ALL TABLES IN SCHEMA plant TO nexora_writer;
